// Domain types shared by the UI, the backend client and the offline queue.

export type ScreenId = 'dashboard' | 'ai' | 'content' | 'inbox' | 'automation' | 'integrations' | 'settings';
export type Platform = 'web' | 'windows' | 'macos' | 'linux' | 'android';
export type Theme = 'light' | 'dark';
export type Range = '7d' | '30d' | '90d';

export interface DeviceInfo {
  /** Server-verified registration id (native: generated by the Rust core and kept in the OS secure store). */
  id: string;
  /** e.g. "RAFIQ-WORKSTATION" or "Chrome on Windows". */
  name: string;
  /** e.g. "Windows 11", "this browser". */
  os: string;
  platform: Platform;
  appVersion: string;
}

export interface Lead {
  id: string;
  name: string;
  title: string | null;
  company: string;
  industry: string | null;
  size: number | null;
  country: string | null;
}

export interface Icp {
  industry: string;
  title: string;
  sizeMin: string;
  sizeMax: string;
  location: string;
}

export interface Prompt { id: string; title: string; text: string }

export type PostStatus = 'Draft' | 'In review' | 'Approved' | 'Scheduled' | 'Published';
export interface Post {
  id: string;
  title: string;
  body: string;
  status: PostStatus;
  /** Calendar day as YYYY-MM-DD, or null when unscheduled. */
  date: string | null;
}

export type Tone = 'Direct' | 'Story' | 'Data';
export interface GeneratedPost { hook: string; body: string; cta: string; tags: string }

export interface Message { me: boolean; text: string; at: string; queued?: boolean }
export interface Conversation {
  id: string;
  name: string;
  company: string;
  channel: string;
  unread: boolean;
  important: boolean;
  intent: string;
  sentiment: string;
  suggestion: string;
  msgs: Message[];
  notes: string[];
}
export interface SavedReply { title: string; text: string }

export type StepType = 'Trigger' | 'Condition' | 'Action' | 'Delay' | 'Approval' | 'Notification' | 'Update' | 'Stop';
export interface Step { type: StepType; label: string }
export interface Workflow { id: string; name: string; on: boolean; steps: Step[] }
export type RunStatus = 'Completed' | 'Awaiting approval';
export interface Run { id: string; workflowId: string; name: string; steps: number; status: RunStatus; at: string }

export type IntegrationCategory = 'AI' | 'CRM' | 'Automation' | 'Communication' | 'Developer' | 'Social';
export interface Integration {
  id: string;
  name: string;
  cat: IntegrationCategory;
  desc: string;
  oauth: boolean;
  connected: boolean;
}

export interface Task { id: string; text: string; due: string; done: boolean }
export interface ActivityItem { text: string; at: string }

export interface Profile { name: string; email: string; workspace: string }
export type ProviderName = 'OpenAI' | 'Google Gemini' | 'Anthropic Claude' | 'OpenRouter';
export const PROVIDER_NAMES: ProviderName[] = ['OpenAI', 'Google Gemini', 'Anthropic Claude', 'OpenRouter'];
export type AiTask = 'Content generation' | 'Lead research' | 'Reply suggestions';
export const AI_TASKS: AiTask[] = ['Content generation', 'Lead research', 'Reply suggestions'];

/** Keys are held server-side; the client only ever learns whether one is stored and verified. */
export interface ProviderState { name: ProviderName; verified: boolean }

export interface OpenRouterModel {
  id: string;
  name: string;
  context: string;
  free: boolean;
  /** Human-readable price per 1M tokens; absent for free models. */
  price?: string;
  available: boolean;
}
export interface OpenRouterSettings { defaultModel: string; fallbackModel: string; monthlyBudgetUsd: string }

export type ConflictRule = 'ask' | 'latest' | 'cloud';
export interface SyncSettings {
  region: string;
  endpoint: string;
  offlineCache: boolean;
  conflict: ConflictRule;
  lastBackupAt: string;
}

export interface Session { id: string; device: string; meta: string; current: boolean }

export interface AiUsage { postsGenerated: number; tokensThisMonth: number; costThisMonthUsd: number }

export interface WorkspacePlan { name: string; hosting: string }

/** Everything the server owns for one workspace, as loaded at start and cached for offline use. */
export interface WorkspaceSnapshot {
  plan: WorkspacePlan;
  profile: Profile;
  leads: Lead[];
  icp: Icp;
  prompts: Prompt[];
  posts: Post[];
  conversations: Conversation[];
  savedReplies: SavedReply[];
  workflows: Workflow[];
  runs: Run[];
  integrations: Integration[];
  tasks: Task[];
  activity: ActivityItem[];
  routing: Record<AiTask, ProviderName>;
  providers: ProviderState[];
  openRouter: OpenRouterSettings;
  mfa: boolean;
  sessions: Session[];
  sync: SyncSettings;
  aiUsage: AiUsage;
  brandVoice: string;
  automationDailyRunLimit: number;
}

export interface DashboardMetrics {
  bars: { label: string; value: number }[];
  /** New, Contacted, Interested, Converted. */
  funnel: [number, number, number, number];
}

// ── licensing ────────────────────────────────────────────────────────────
export interface LicenseState {
  keyMasked: string;
  plan: string;
  priceLabel: string;
  renewsOn: string;
  deviceName: string;
  deviceOs: string;
  activatedAt: string;
  activeDevices: number;
  maxDevices: number;
  /** Native only: offline access is allowed until this instant without revalidation. */
  graceUntil?: string;
}
export interface LicenseEvent { text: string; at: string }

export type ActivationFailure =
  | { code: 'invalid' }
  | { code: 'expired'; expiredOn?: string }
  | { code: 'revoked' }
  | { code: 'in_use'; deviceName?: string; deviceOs?: string; activatedAt?: string }
  | { code: 'unavailable' };

export type ActivationResult =
  | { ok: true; license: LicenseState; entitlementToken: string; /** Native only: kept in the OS secure store. */ sessionToken?: string }
  | ({ ok: false } & ActivationFailure);

// ── sync ─────────────────────────────────────────────────────────────────
/** One write. `id` is the idempotency key, so replaying the offline queue cannot duplicate it. */
export interface Change {
  id: string;
  entity: string;
  op: 'upsert' | 'delete';
  entityId: string;
  data?: unknown;
  at: string;
}
